function exactRows(rows, expectedPaths) {
  return (
    Array.isArray(rows) &&
    rows.length === expectedPaths.length &&
    rows.every((row, index) =>
      row?.claim === CLAIM &&
      row.path === expectedPaths[index] &&
      /^[0-9a-f]{64}$/u.test(row.currentDigest) &&
      /^[0-9a-f]{64}$/u.test(row.expectedDigest) &&
      Array.isArray(row.replacements) &&
      row.replacements.length > 0
    )
  );
}

export function traceRetentionRootSourceReconstruction(path) {
  return POST_TRACE_RETENTION_ROOT_SOURCE_RECONSTRUCTIONS.find((row) => row.path === path);
}

export function validateTraceRetentionRootHistoricalTransition({
  transition = TRACE_RETENTION_ROOT_HISTORICAL_TRANSITION,
  sourceReconstructions = POST_TRACE_RETENTION_ROOT_SOURCE_RECONSTRUCTIONS,
  compiledReconstructions = POST_TRACE_RETENTION_ROOT_COMPILED_RECONSTRUCTIONS,
} = {}) {
  if (
    transition?.claim !== CLAIM ||
    transition.predecessorCommit !== PREDECESSOR_COMMIT ||
    transition.successorCommit !== SUCCESSOR_COMMIT ||
    transition.compiledInventory?.predecessor?.count !== 317 ||
    transition.compiledInventory.predecessor.digest !== '34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67' ||
    transition.compiledInventory?.successor?.count !== 317 ||
    transition.compiledInventory.successor.digest !== '34aa878fbfb82d4235547aed9abec7cd1d6c848f68d990ad9cba915d1def5d67' ||
    !exactRows(sourceReconstructions, EXPECTED_SOURCE_PATHS) ||
    !exactRows(compiledReconstructions, EXPECTED_COMPILED_PATHS)
  ) {
    throw new TypeError('trace-retention root historical transition immutable identity changed');
  }
  return true;
}
